CREATE TABLE public.contact_messages (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL, company TEXT, topic TEXT NOT NULL DEFAULT 'general' CONSTRAINT contact_messages_topic_check CHECK (topic IN ('general','custom_plan','support','affiliate','press')), plan TEXT, message TEXT NOT NULL, lang TEXT NOT NULL DEFAULT 'es' CONSTRAINT contact_messages_lang_check CHECK (lang IN ('es','en')), source TEXT NOT NULL DEFAULT 'web', forwarded BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now()); GRANT ALL ON public.contact_messages TO service_role; ALTER TABLE public.contact_messages ENABLE ROW LEVEL SECURITY;